function getCheckoutSummarySkeletonHtml(itemCount = 2) {
    const count = Math.max(1, Math.min(itemCount, 4));
    return Array(count).fill(0).map(() => `
        <div class="sk-checkout-item skeleton-checkout-item" aria-hidden="true">
            <div class="sk-checkout-thumb skeleton-base"></div>
            <div class="sk-checkout-info">
                <div class="sk-checkout-title skeleton-base"></div>
                <div class="sk-checkout-meta skeleton-base"></div>
            </div>
            <div class="sk-checkout-price skeleton-base"></div>
        </div>
    `).join("");
}

function showCheckoutSummarySkeleton() {
    const itemsContainer = document.getElementById("checkout-items");
    const countEl = document.getElementById("checkout-item-count");
    const subtotalEl = document.getElementById("checkout-subtotal");
    const shippingEl = document.getElementById("checkout-shipping");
    const totalEl = document.getElementById("checkout-total");
    
    if (itemsContainer) {
        const count = typeof cart !== "undefined" && cart.length ? cart.length : 2;
        itemsContainer.innerHTML = getCheckoutSummarySkeletonHtml(count);
    }
    if (countEl) {
        countEl.innerHTML = `<span class="skeleton-base skeleton-inline" style="width:16px; height:16px; border-radius:50%; display:inline-block;"></span>`;
    }
    if (subtotalEl) {
        subtotalEl.innerHTML = `<span class="skeleton-base skeleton-inline" style="width:65px; height:18px;"></span>`;
    }
    if (shippingEl) {
        shippingEl.innerHTML = `<span class="skeleton-base skeleton-inline" style="width:110px; height:14px;"></span>`;
    }
    if (totalEl) {
        totalEl.innerHTML = `<span class="skeleton-base skeleton-inline" style="width:85px; height:26px;"></span>`;
    }
}
window.getProductGridSkeletonHtml = getProductGridSkeletonHtml;
window.getCheckoutSummarySkeletonHtml = getCheckoutSummarySkeletonHtml;
window.showCheckoutSummarySkeleton = showCheckoutSummarySkeleton;

function getBlurPlaceholderSvg(product) {
    const isMasculine = product && product.gender === "Masculine";
    const isFeminine = product && product.gender === "Feminine";
    const accentColor = isFeminine ? "#d48b9c" : (isMasculine ? "#7ca5b8" : "#cba35c");
    
    const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 360" width="100%" height="100%">
        <defs>
            <radialGradient id="amb" cx="50%" cy="50%" r="50%">
                <stop offset="0%" stop-color="${accentColor}" stop-opacity="0.28"/>
                <stop offset="60%" stop-color="#080d0c" stop-opacity="0.85"/>
                <stop offset="100%" stop-color="#020606" stop-opacity="0.98"/>
            </radialGradient>
            <filter id="bl" x="-30%" y="-30%" width="160%" height="160%">
                <feGaussianBlur stdDeviation="10"/>
            </filter>
        </defs>
        <rect width="300" height="360" fill="url(#amb)"/>
        <g filter="url(#bl)" opacity="0.65">
            <rect x="120" y="55" width="60" height="30" rx="3" fill="${accentColor}" opacity="0.7"/>
            <rect x="135" y="85" width="30" height="18" fill="${accentColor}" opacity="0.5"/>
            <path d="M 90 105 L 210 105 C 220 105 228 115 228 125 L 228 275 C 228 290 215 300 200 300 L 100 300 C 85 300 72 290 72 275 L 72 125 C 72 115 80 105 90 105 Z" fill="${accentColor}" opacity="0.45"/>
            <circle cx="150" cy="200" r="35" fill="#fff" opacity="0.2"/>
        </g>
    </svg>`;
    return "data:image/svg+xml;charset=utf-8," + encodeURIComponent(svg);
}

let catalogImageObserver = null;
function initLazyImageObserver() {
    if (!("IntersectionObserver" in window)) {
        document.querySelectorAll("img.blur-up-img[data-src]").forEach(img => {
            if (img.dataset.src && img.src !== img.dataset.src) {
                img.src = img.dataset.src;
            }
        });
        return;
    }

    if (catalogImageObserver) {
        catalogImageObserver.disconnect();
    }

    catalogImageObserver = new IntersectionObserver((entries, observer) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                const img = entry.target;
                observer.unobserve(img);
                const realSrc = img.dataset.src;
                if (realSrc && img.src !== realSrc) {
                    const temp = new Image();
                    temp.src = realSrc;
                    temp.onload = () => {
                        img.src = realSrc;
                        handleLuxuryImageLoad(img);
                    };
                    temp.onerror = () => {
                        img.src = realSrc;
                        handleImageError(img);
                    };
                }
            }
        });
    }, {
        rootMargin: "300px 0px 300px 0px",
        threshold: 0.01
    });

    document.querySelectorAll("img.blur-up-img[data-src]:not(.is-loaded)").forEach(img => {
        catalogImageObserver.observe(img);
    });
}
