function renderCheckout() {
    const itemsContainer = document.getElementById("checkout-items");
    const countEl = document.getElementById("checkout-item-count");
    if (!itemsContainer) return;

    let subtotal = 0;
    let totalItems = 0;
    let totalSavings = 0;

    cart.forEach(item => {
        const price = Number(item.activePrice) || 0;
        const qty = Number(item.qty) || 0;
        const size = item.selectedSize || "6ml";
        const regPrice = size === "30ml" ? 1950 : (size === "10ml" ? 1050 : 750);
        totalSavings += (regPrice - price) * qty;
        subtotal += price * qty;
        totalItems += qty;
    });

    if (countEl) countEl.innerText = totalItems;

    const cityInput = document.getElementById("billing-city");
    const selectedCity = cityInput ? cityInput.value : "";
    const shipping = getShippingDetails(subtotal, selectedCity);

    const subtotalEl = document.getElementById("checkout-subtotal");
    const shippingEl = document.getElementById("checkout-shipping");
    const totalEl = document.getElementById("checkout-total");

    if (subtotalEl) subtotalEl.innerText = `${subtotal.toLocaleString()}৳`;

    if (shippingEl) {
        shippingEl.innerText = shipping.text;
        if (!shipping.isCalculated) {
            shippingEl.style.fontSize = "0.72rem";
            shippingEl.style.color = "var(--gold-muted)";
            shippingEl.style.fontWeight = "400";
        } else {
            shippingEl.style.fontSize = "0.85rem";
            shippingEl.style.color = shipping.fee === 0 ? "#4ade80" : "var(--white)";
            shippingEl.style.fontWeight = "700";
        }
    }

    let discountAmount = 0;
    const discountRow = document.getElementById("discount-row");
    const discountLabel = document.getElementById("discount-label");
    const discountEl = document.getElementById("checkout-discount");

    if (appliedDiscount) {
        discountAmount = appliedDiscount.type === "percentage" 
            ? Math.round((subtotal * appliedDiscount.value) / 100) 
            : Math.min(subtotal, appliedDiscount.value);

        if (discountLabel && discountEl && discountRow) {
            let labelText = `${appliedDiscount.code}`;
            if (appliedDiscount.type === "percentage") {
                labelText += ` - ${appliedDiscount.value}%`;
            } else {
                labelText += ` - ${appliedDiscount.value}৳`;
            }
            if (appliedDiscount.freeShipping) labelText += " + Free Shipping";
            discountLabel.innerText = labelText;
            discountRow.style.display = "flex";
            discountEl.innerText = `-${discountAmount}৳`;
        }
    } else if (discountRow) {
        discountRow.style.display = "none";
    }

    const savingsRow = document.getElementById("savings-row");
    const savingsEl = document.getElementById("checkout-savings");
    const combinedSavings = totalSavings + discountAmount;
    if (combinedSavings > 0 && savingsRow && savingsEl) {
        savingsRow.style.display = "flex";
        savingsEl.innerText = `${combinedSavings.toLocaleString()}৳`;
    } else if (savingsRow) {
        savingsRow.style.display = "none";
    }

    const calculatedShippingFee = shipping.isCalculated ? shipping.fee : 0;
    const finalTotal = Math.max(0, subtotal - discountAmount + calculatedShippingFee);
    if (totalEl) totalEl.innerText = `${finalTotal.toLocaleString()}৳`;

    // Populate checkout items list in sidebar
    let itemsHtml = "";
    cart.forEach(item => {
        const price = Number(item.activePrice) || 0;
        const qty = Number(item.qty) || 0;
        const size = item.selectedSize || "6ml";
        itemsHtml += `
            <div class="checkout-item-row interactive" style="display:flex; gap:14px; align-items:center; padding:12px 0; border-bottom:1px solid rgba(255,255,255,0.05); position:relative;">
                <button class="checkout-item-remove-btn" onclick="event.stopPropagation(); removeFromCheckout('${item.id}', '${size}')" title="Remove Item" style="position:absolute; top:8px; right:0; background:none; border:none; color:var(--text-dim); cursor:pointer; padding:4px;">
                    <i data-lucide="x" size="14"></i>
                </button>
                <div class="checkout-item-img-container" style="width:50px; height:55px; flex-shrink:0; background:rgba(0,0,0,0.3); border:1px solid rgba(203,163,92,0.15); border-radius:2px; display:flex; align-items:center; justify-content:center;">
                    <img src="${item.img}" alt="${item.name}" loading="lazy" style="max-width:85%; max-height:85%; object-fit:contain" referrerPolicy="no-referrer">
                </div>
                <div class="checkout-item-info" style="flex:1; min-width:0; padding-right:18px;">
                    <div class="checkout-item-name" style="font-size:0.8rem; font-weight:600; color:var(--text-white); white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">${item.name}</div>
                    <div class="checkout-item-meta" style="font-size:0.65rem; color:var(--gold-muted); margin-top:2px;">
                        <span>${qty} × ${size === "30ml" ? "30ml" : size.toUpperCase()}</span>
                    </div>
                </div>
                <div class="checkout-item-total" style="text-align:right;">
                    <div class="checkout-item-total-value" style="font-size:0.85rem; font-weight:700; color:var(--gold-bright); font-family:var(--font-mono);">${(price * qty).toLocaleString()}৳</div>
                </div>
            </div>
        `;
    });
    itemsContainer.innerHTML = itemsHtml;
    itemsContainer.classList.remove("checkout-data-loaded");
    void itemsContainer.offsetWidth;
    itemsContainer.classList.add("checkout-data-loaded");
    if (window.lucide) lucide.createIcons();
}
