let activeModalTrigger = null;
function updateFloatingControls(){
    const isHidden = document.body.classList.contains("cart-open") || document.body.classList.contains("checkout-active") || (document.getElementById("cart-overlay") && document.getElementById("cart-overlay").classList.contains("open")) || (document.getElementById("checkout-view") && document.getElementById("checkout-view").style.display !== "none");
    const btt = document.getElementById("back-to-top");
    const waf = document.getElementById("whatsapp-float");
    if(btt) btt.style.setProperty("display", isHidden ? "none" : "", "important");
    if(waf) waf.style.setProperty("display", isHidden ? "none" : "", "important");
}
function trapModalFocus(container, e){
    if(e.key !== "Tab") return;
    const focusables = Array.from(container.querySelectorAll("a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex='-1'])")).filter(el => el.offsetParent !== null);
    if(focusables.length === 0){ e.preventDefault(); return; }
    const first = focusables[0];
    const last = focusables[focusables.length - 1];
    if(e.shiftKey){
        if(document.activeElement === first || !container.contains(document.activeElement)){
            e.preventDefault();
            last.focus();
        }
    } else {
        if(document.activeElement === last || !container.contains(document.activeElement)){
            e.preventDefault();
            first.focus();
        }
    }
}
document.addEventListener("keydown", (e) => {
    if(e.key === "Escape"){
        const lb = document.getElementById("lightbox");
        if(lb && (lb.classList.contains("active") || lb.style.display === "flex")){ closeLightbox(); return; }
        const bn = document.getElementById("buy-now-modal-overlay");
        if(bn && bn.classList.contains("active")){ closeBuyNowModal(); return; }
        const sp = document.getElementById("scent-profile-modal");
        if(sp && sp.classList.contains("active")){ closeScentProfile(); return; }
        const sf = document.getElementById("scent-finder-overlay");
        if(sf && (sf.classList.contains("active") || sf.style.display === "block")){ closeScentFinder(); return; }
        const co = document.getElementById("cart-overlay");
        if(co && co.classList.contains("open")){ toggleCart(false); return; }
        const mm = document.getElementById("mobile-menu");
        if(mm && (mm.classList.contains("active") || document.body.classList.contains("menu-open"))){ closeMobileMenu(); return; }
    }
    const openModals = [
        document.getElementById("buy-now-modal-overlay")?.classList.contains("active") ? document.getElementById("buy-now-modal-overlay") : null,
        document.getElementById("scent-profile-modal")?.classList.contains("active") ? document.getElementById("scent-profile-modal") : null,
        (document.getElementById("scent-finder-overlay")?.classList.contains("active") || document.getElementById("scent-finder-overlay")?.style.display === "block") ? document.getElementById("scent-finder-overlay") : null,
        document.getElementById("cart-overlay")?.classList.contains("open") ? document.querySelector(".cart-drawer") : null,
        document.getElementById("mobile-menu")?.classList.contains("active") ? document.getElementById("mobile-menu") : null
    ].filter(Boolean);
    if(openModals.length > 0){
        trapModalFocus(openModals[openModals.length - 1], e);
    }
});
